SELECT *, AVG(cost) OVER w_running AS cost_avg_3, LAST_VALUE(carrier, TRUE) OVER w_running_2 AS last_known_carrier, LAG(cost, 1) OVER (PARTITION BY status ORDER BY delivered_date, id) AS prev_cost, RANK() OVER (ORDER BY cost DESC NULLS FIRST) AS cost_rank, ROW_NUMBER() OVER (PARTITION BY status ORDER BY cost DESC, id) AS event_seq FROM shipments WINDOW w_running AS (PARTITION BY carrier, order_id ORDER BY shipped_date, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW), w_running_2 AS (PARTITION BY carrier ORDER BY cost, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW);
